package br.com.nuvemtv;
import android.graphics.*;import android.media.*;import android.os.Looper;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w960dp-h540dp-land-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SocialIntegrationTest {
 MainActivity a;ActivityController<MainActivity> controller;
 @Before public void start(){RuntimeEnvironment.getApplication().getSharedPreferences("vault",0).edit().clear().commit();RuntimeEnvironment.getApplication().getSharedPreferences("social-state",0).edit().clear().commit();RuntimeEnvironment.getApplication().getSharedPreferences("settings",0).edit().clear().putString("language","pt-BR").commit();controller=Robolectric.buildActivity(MainActivity.class).setup();a=controller.get();}
 @After public void finish(){controller.pause().stop().destroy();}
 void layout(){Shadows.shadowOf(Looper.getMainLooper()).idle();a.root.measure(View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY));a.root.layout(0,0,1920,1080);a.root.getViewTreeObserver().dispatchOnGlobalLayout();Shadows.shadowOf(Looper.getMainLooper()).idle();}
 @Test public void groupAndBlockStayInsideTheApp()throws Exception{JSONObject user=Json.obj("xuid","123","gamertag","Example","displayPicRaw","");a.person(user);LibraryUiTest.find(a.root,"Convidar para um novo grupo").performClick();assertNotNull(a.officialSocial);assertTrue(a.officialSocial.isExpanded());assertEquals("https://www.xbox.com/pt-BR/play/user/Example",a.officialSocial.web.getUrl());assertNull(Shadows.shadowOf(a).getNextStartedActivity());OfficialSocial previous=a.officialSocial;previous.minimize();assertTrue(previous.closed);assertNull(a.officialSocial);a.person(user);LibraryUiTest.find(a.root,"Bloquear usuário").performClick();assertTrue(a.officialSocial.isExpanded());assertNull(Shadows.shadowOf(a).getNextStartedActivity());}
 @Test public void officialSessionViewIsReusedAcrossNativeScreens(){a.openSocial("");OfficialSocial console=a.officialSocial;WebView original=console.web;console.microphoneRequested=true;assertTrue(original.getSettings().getJavaScriptEnabled());assertTrue(original.getSettings().getDomStorageEnabled());assertFalse(original.getSettings().getAllowFileAccess());assertFalse(original.getSettings().getAllowContentAccess());console.minimize();a.settings();assertSame(original,a.officialSocial.web);assertFalse(console.isExpanded());assertNotNull(console.panel.getParent());a.closeOfficialSocial(false);assertNull(a.officialSocial);assertTrue(console.closed);}
 @Test public void officialNavigationAndAudioPermissionHaveStrictOrigins(){assertTrue(OfficialSocial.permitted("https://www.xbox.com/pt-BR/play/user/Example"));assertTrue(OfficialSocial.permitted("https://login.live.com/oauth20_authorize.srf"));assertTrue(OfficialSocial.microphoneOrigin("https://www.xbox.com/"));for(String url:new String[]{"http://www.xbox.com","https://www.xbox.com.evil.test/","https://u@www.xbox.com/","https://www.xbox.com:444/","javascript:alert(1)","file:///test"}){assertFalse(url,OfficialSocial.permitted(url));assertFalse(url,OfficialSocial.microphoneOrigin(url));}assertFalse(OfficialSocial.microphoneOrigin("https://login.live.com"));assertFalse(OfficialSocial.microphoneOrigin("https://www.xbox.com/profile"));}
 @Test public void voiceInformationIsOptInAfterMicrophonePermission(){a.settings();Switch info=a.root.findViewWithTag("setting:voiceStats"),mic=a.root.findViewWithTag("setting:microphone");assertNotNull(info);assertFalse(info.isChecked());assertFalse(info.isEnabled());Shadows.shadowOf(a.getApplication()).grantPermissions(android.Manifest.permission.RECORD_AUDIO);mic.setChecked(true);assertTrue(info.isEnabled());assertFalse(a.prefs.getBoolean("voiceStats",false));info.setChecked(true);assertTrue(a.prefs.getBoolean("voiceStats",false));}
 @Test public void profileAndSearchRowsBothContainPictures()throws Exception{JSONObject user=Json.obj("xuid","123","gamertag","Photo","displayPicRaw","https://avatar-ssl.xboxlive.com/avatar/123/avatarpic-l.png");a.friends();LinearLayout list=a.root.findViewWithTag("people-list");list.removeAllViews();a.peopleRows(list,"Resultados",Json.arr(user));layout();assertEquals(1,a.avatarBindings.size());assertEquals("Photo",a.avatarBindings.get(0).view.getContentDescription().toString());assertTrue(a.avatarBindings.get(0).url.contains("w=96"));a.person(user);layout();assertEquals(1,a.avatarBindings.size());assertTrue(a.avatarBindings.get(0).view.getWidth()>0);assertEquals("Photo",a.avatarBindings.get(0).view.getContentDescription().toString());}
 @Test public void audioUsesMediaStreamWithoutChangingUserVolume(){AudioManager manager=(AudioManager)a.getSystemService(android.content.Context.AUDIO_SERVICE);int before=manager.getStreamVolume(AudioManager.STREAM_MUSIC);GameAudio sound=new GameAudio(a);assertEquals(AudioAttributes.USAGE_GAME,GameAudio.attributes().getUsage());assertEquals(AudioAttributes.CONTENT_TYPE_MUSIC,GameAudio.attributes().getContentType());sound.start(false);assertEquals(before,manager.getStreamVolume(AudioManager.STREAM_MUSIC));sound.close();GameAudio mixed=new GameAudio(a);mixed.start(true);assertFalse(mixed.requested);mixed.close();}
 @Test public void socialViewSurvivesChangingToTheGameContainerWithoutRetainingLibraryImages(){a.openSocial("");OfficialSocial console=a.officialSocial;WebView original=console.web;console.microphoneRequested=true;console.minimize();a.playing=true;a.releaseLibraryViews();FrameLayout stage=new FrameLayout(a);a.setContentView(stage);a.attachOfficialSocial();assertSame(original,a.officialSocial.web);assertNotNull(original.getParent());assertFalse(console.isExpanded());assertTrue(a.images.isPaused());assertNull(a.root);assertTrue(a.avatarBindings.isEmpty());a.playing=false;a.home();}
 @Test public void gamepadDoesNotControlTheGameWhileSocialIsExpanded(){a.openSocial("");layout();a.playing=true;android.view.KeyEvent key=new android.view.KeyEvent(0,1,android.view.KeyEvent.ACTION_DOWN,android.view.KeyEvent.KEYCODE_BUTTON_A,0,0,1,0,0,android.view.InputDevice.SOURCE_GAMEPAD);a.dispatchKeyEvent(key);assertEquals(0,a.pad.buttons);a.officialSocial.microphoneRequested=true;a.officialSocial.minimize();a.dispatchKeyEvent(key);assertNotEquals(0,a.pad.buttons);a.officialSocial.expand();assertEquals(0,a.pad.buttons);a.playing=false;}
 @Test public void minimizingIdleSocialDestroysTheRemotePageAndLeavesNoFloatingButton(){a.openSocial("");OfficialSocial page=a.officialSocial;page.minimize();assertNull(a.officialSocial);assertTrue(page.closed);assertNull(page.panel.getParent());assertNull(LibraryUiTest.find(a.root,"Social Xbox"));}
 @Test public void backReturnsFocusFromWebToControlsAndThenExits(){a.openSocial("");OfficialSocial page=a.officialSocial;page.web.requestFocus();assertFalse(page.controls.hasFocus());assertTrue(page.routeKey(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_BACK)));assertTrue(page.routeKey(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_BACK)));assertTrue(page.controls.hasFocus());assertFalse(page.routeKey(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_BACK)));a.onBackPressed();assertTrue(page.closed);assertNull(a.officialSocial);}
 @Test public void profileHasOneOfficialProfileButtonAndKnownRelationshipLabels()throws Exception{JSONObject user=Json.obj("xuid","123","gamertag","Example","detail",Json.obj("isFriendRequestSent",true,"isFollowedByCaller",true));a.person(user);assertNotNull(LibraryUiTest.find(a.root,"Amizade solicitada"));assertNotNull(LibraryUiTest.find(a.root,"Seguindo"));assertNull(LibraryUiTest.find(a.root,"Social Xbox no aplicativo"));LibraryUiTest.find(a.root,"Ver perfil no Xbox").performClick();assertEquals("https://www.xbox.com/pt-BR/play/user/Example",a.officialSocial.web.getUrl());}
 void until(java.util.function.BooleanSupplier ready)throws Exception{long deadline=System.currentTimeMillis()+3000;while(!ready.getAsBoolean()&&System.currentTimeMillis()<deadline){Thread.sleep(10);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertTrue(ready.getAsBoolean());}
 @Test public void acceptedFriendAndFollowUpdateButtonsAndRejectedActionsDoNot()throws Exception{JSONObject user=Json.obj("xuid","123","gamertag","Example");a.signedIn=true;a.socialApi=new SocialApi((m,u,c,b)->u.contains("peoplehub")?Json.obj("people",Json.arr(user)):new JSONObject());a.person(user);LibraryUiTest.find(a.root,"Solicitar amizade").performClick();org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getButton(android.content.DialogInterface.BUTTON_POSITIVE).performClick();until(()->LibraryUiTest.find(a.root,"Amizade solicitada")!=null);LibraryUiTest.find(a.root,"Seguir").performClick();org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getButton(android.content.DialogInterface.BUTTON_POSITIVE).performClick();until(()->LibraryUiTest.find(a.root,"Seguindo")!=null);assertFalse(LibraryUiTest.find(a.root,"Amizade solicitada").isEnabled());assertFalse(LibraryUiTest.find(a.root,"Seguindo").isEnabled());}
 @Test public void conversationDisplaysNestedHistoryAndAcceptedOutgoingMessage()throws Exception{JSONObject user=Json.obj("xuid","123","gamertag","Pessoa");a.signedIn=true;a.socialApi=new SocialApi((m,u,c,b)->m.equals("POST")?Json.obj("messageId","sent-1"):Json.obj("messages",Json.arr(Json.obj("messageId","old","sender","123","timestamp","2026-01-01T10:00:00Z","contentPayload",Json.obj("content",Json.obj("parts",Json.arr(Json.obj("contentType","text","text","Mensagem recebida"))))))));a.conversation(user);until(()->a.conversationText.getText().toString().contains("Mensagem recebida"));((EditText)a.root.findViewWithTag("first-control")).setText("Resposta enviada");LibraryUiTest.find(a.root,"Enviar").performClick();org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getButton(android.content.DialogInterface.BUTTON_POSITIVE).performClick();until(()->a.conversationText.getText().toString().contains("Resposta enviada"));assertTrue(a.conversationText.getText().toString().contains("Mensagem recebida"));assertTrue(a.conversationText.getText().toString().contains("Você"));}
}
